import sys

# Increase recursion depth to handle deep DSU trees if necessary
sys.setrecursionlimit(3000000)

def solve():
    # Read all input at once for speed
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T_str = next(iterator)
        T = int(T_str)
    except StopIteration:
        return

    MOD = 998244353

    for _ in range(T):
        try:
            H = int(next(iterator))
            W = int(next(iterator))
        except StopIteration:
            break

        grid = []
        for _ in range(H):
            grid.append(next(iterator))

        # Check row parities
        # For a valid configuration, each row must have an even number of 'A's
        possible = True
        for r in grid:
            if r.count('A') % 2 != 0:
                possible = False
                break

        if not possible:
            print(0)
            continue

        # Check col parities
        # For a valid configuration, each column must have an even number of 'A's
        col_counts = [0] * W
        for r in grid:
            for j, char in enumerate(r):
                if char == 'A':
                    col_counts[j] += 1

        for c in col_counts:
            if c % 2 != 0:
                possible = False
                break

        if not possible:
            print(0)
            continue

        # DSU initialization
        # We have variables c_0...c_{H-1} and d_0...d_{W-1}
        # Nodes 0..H-1 represent c_i
        # Nodes H..H+W-1 represent d_j
        parent = list(range(H + W))
        diff = [0] * (H + W)
        components = H + W

        def find(i):
            if parent[i] == i:
                return i, 0
            root, root_diff = find(parent[i])
            parent[i] = root
            diff[i] ^= root_diff
            return root, diff[i]

        # col_t[j] stores t_{i, j} for the current row i
        # Initially for i=0, t_{0, j} = 0 (base solution)
        col_t = [0] * W

        consistent = True

        for i in range(H):
            row_str = grid[i]
            current_r = 0 # r_{i, 0} = 0 (base solution)

            for j in range(W):
                # Update current_r for r_{i, j}
                # The constraint is R_{i, j} != R_{i, j-1} if S_{i, j} == 'A'
                # So r_{i, j} = r_{i, j-1} ^ 1 if 'A', else r_{i, j-1}
                # For j=0, current_r is 0.
                if j > 0:
                    if row_str[j] == 'A':
                        current_r ^= 1

                # current_r is r_{i, j}
                t_val = col_t[j]
                # K_{i, j} = r_{i, j} ^ t_{i, j}
                K = current_r ^ t_val

                if row_str[j] == 'B':
                    # For Type B tiles, we have constraint R_{i, j} != T_{i, j}
                    # In terms of variables: (r_{i, j} ^ c_i) != (t_{i, j} ^ d_j)
                    # <=> c_i ^ d_j != r_{i, j} ^ t_{i, j}
                    # <=> c_i ^ d_j != K
                    # <=> c_i ^ d_j = 1 ^ K
                    w = 1 ^ K

                    # Union c_i (node i) and d_j (node H+j)
                    u = i
                    v = H + j

                    root_u, val_u = find(u)
                    root_v, val_v = find(v)

                    if root_u != root_v:
                        parent[root_u] = root_v
                        # We need val[root_u] ^ val[root_v] = w ^ val_u ^ val_v
                        diff[root_u] = val_u ^ val_v ^ w
                        components -= 1
                    else:
                        # Check consistency
                        if (val_u ^ val_v) != w:
                            consistent = False
                            break

                # Update col_t for next row
                # The constraint is T_{i+1, j} = T_{i, j} ^ 1 if S_{i, j} == 'A'
                # So t_{i+1, j} = t_{i, j} ^ 1 if 'A'
                if row_str[j] == 'A':
                    col_t[j] ^= 1

            if not consistent:
                break

        if consistent:
            # Each connected component in the constraint graph contributes a factor of 2
            ans = pow(2, components, MOD)
            print(ans)
        else:
            print(0)

if __name__ == '__main__':
    solve()

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        # Directions: 0: NE, 1: SE, 2: SW, 3: NW
        # Vectors: (-1, 1), (1, 1), (1, -1), (-1, -1)
        # Clockwise order: NE -> SE -> SW -> NW
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        # L[r][c][d] stores max length of valid straight segment ending at (r, c) coming from direction d
        # Initialize with 0
        L = [[[0] * 4 for _ in range(m)] for _ in range(n)]

        # Compute L
        for d in range(4):
            dr, dc = dirs[d]
            # Determine iteration order to ensure dependencies are met
            # We need L[pr][pc][d] where (pr, pc) = (r - dr, c - dc)
            # So we need to process (r - dr, c - dc) before (r, c)
            if dr > 0:
                r_range = range(n)
            else:
                r_range = range(n - 1, -1, -1)

            if dc > 0:
                c_range = range(m)
            else:
                c_range = range(m - 1, -1, -1)

            for r in r_range:
                for c in c_range:
                    if grid[r][c] == 1:
                        L[r][c][d] = 1
                    else:
                        pr, pc = r - dr, c - dc
                        if 0 <= pr < n and 0 <= pc < m:
                            prev_len = L[pr][pc][d]
                            if prev_len > 0:
                                # Check pattern for index prev_len
                                # Index prev_len corresponds to current cell
                                # Pattern: if index is odd -> 2, if even -> 0
                                # Note: index 0 is 1, but prev_len >= 1 here
                                if prev_len % 2 == 1:
                                    expected = 2
                                else:
                                    expected = 0

                                if grid[r][c] == expected:
                                    L[r][c][d] = prev_len + 1
                                else:
                                    L[r][c][d] = 0
                            else:
                                L[r][c][d] = 0
                        else:
                            L[r][c][d] = 0

        # Z[r][c][d] and T[r][c][d]
        # Z: starts with 0 (pattern 0, 2, 0...)
        # T: starts with 2 (pattern 2, 0, 2...)
        Z = [[[0] * 4 for _ in range(m)] for _ in range(n)]
        T = [[[0] * 4 for _ in range(m)] for _ in range(n)]

        # Compute Z and T
        # Dependency: (r, c) depends on (r + dr, c + dc)
        # So we need to process (r + dr, c + dc) before (r, c)
        for d in range(4):
            dr, dc = dirs[d]

            if dr > 0:
                r_range = range(n - 1, -1, -1)
            else:
                r_range = range(n)

            if dc > 0:
                c_range = range(m - 1, -1, -1)
            else:
                c_range = range(m)

            for r in r_range:
                for c in c_range:
                    nr, nc = r + dr, c + dc

                    # Compute Z[r][c][d]
                    if grid[r][c] == 0:
                        length = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            length += T[nr][nc][d]
                        Z[r][c][d] = length
                    else:
                        Z[r][c][d] = 0

                    # Compute T[r][c][d]
                    if grid[r][c] == 2:
                        length = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            length += Z[nr][nc][d]
                        T[r][c][d] = length
                    else:
                        T[r][c][d] = 0

        max_len = 0

        # Combine results
        for r in range(n):
            for c in range(m):
                for d in range(4):
                    len_pre = L[r][c][d]
                    if len_pre == 0:
                        continue

                    # Straight segment
                    if len_pre > max_len:
                        max_len = len_pre

                    # Turn
                    # Turn possible if len_pre >= 2
                    if len_pre >= 2:
                        next_d = (d + 1) % 4
                        nr, nc = r + dirs[next_d][0], c + dirs[next_d][1]

                        if 0 <= nr < n and 0 <= nc < m:
                            # Neighbor index is len_pre
                            # If len_pre is odd, neighbor index is odd -> need 2 -> T table
                            # If len_pre is even, neighbor index is even -> need 0 -> Z table
                            if len_pre % 2 == 1:
                                ext_len = T[nr][nc][next_d]
                            else:
                                ext_len = Z[nr][nc][next_d]

                            total_len = len_pre + ext_len
                            if total_len > max_len:
                                max_len = total_len

        return max_len

