import sys
from collections import defaultdict
from bisect import bisect_right

def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
        Sx = int(next(iterator))
        Sy = int(next(iterator))

        houses = []
        for _ in range(N):
            hx = int(next(iterator))
            hy = int(next(iterator))
            houses.append((hx, hy))

        # Store intervals for vertical and horizontal moves
        # Vertical segments: x -> list of (y1, y2)
        vert_intervals = defaultdict(list)
        # Horizontal segments: y -> list of (x1, x2)
        horz_intervals = defaultdict(list)

        curr_x, curr_y = Sx, Sy

        for _ in range(M):
            d = next(iterator)
            c = int(next(iterator))

            if d == 'U':
                next_y = curr_y + c
                # Vertical segment at x = curr_x from curr_y to next_y
                if curr_y < next_y:
                    vert_intervals[curr_x].append((curr_y, next_y))
                else:
                    vert_intervals[curr_x].append((next_y, curr_y))
                curr_y = next_y
            elif d == 'D':
                next_y = curr_y - c
                # Vertical segment at x = curr_x from curr_y to next_y
                if curr_y < next_y:
                    vert_intervals[curr_x].append((curr_y, next_y))
                else:
                    vert_intervals[curr_x].append((next_y, curr_y))
                curr_y = next_y
            elif d == 'L':
                next_x = curr_x - c
                # Horizontal segment at y = curr_y from curr_x to next_x
                if curr_x < next_x:
                    horz_intervals[curr_y].append((curr_x, next_x))
                else:
                    horz_intervals[curr_y].append((next_x, curr_x))
                curr_x = next_x
            elif d == 'R':
                next_x = curr_x + c
                # Horizontal segment at y = curr_y from curr_x to next_x
                if curr_x < next_x:
                    horz_intervals[curr_y].append((curr_x, next_x))
                else:
                    horz_intervals[curr_y].append((next_x, curr_x))
                curr_x = next_x

    except StopIteration:
        pass

    # Merge overlapping intervals for vertical segments
    merged_vert = {}
    vert_starts = {}
    vert_ends = {}

    for x, intervals in vert_intervals.items():
        intervals.sort()
        merged = []
        if not intervals:
            merged_vert[x] = []
            vert_starts[x] = []
            vert_ends[x] = []
            continue

        curr_start, curr_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= curr_end:
                if end > curr_end:
                    curr_end = end
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = start, end
        merged.append((curr_start, curr_end))

        merged_vert[x] = merged
        vert_starts[x] = [iv[0] for iv in merged]
        vert_ends[x] = [iv[1] for iv in merged]

    # Merge overlapping intervals for horizontal segments
    merged_horz = {}
    horz_starts = {}
    horz_ends = {}

    for y, intervals in horz_intervals.items():
        intervals.sort()
        merged = []
        if not intervals:
            merged_horz[y] = []
            horz_starts[y] = []
            horz_ends[y] = []
            continue

        curr_start, curr_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= curr_end:
                if end > curr_end:
                    curr_end = end
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = start, end
        merged.append((curr_start, curr_end))

        merged_horz[y] = merged
        horz_starts[y] = [iv[0] for iv in merged]
        horz_ends[y] = [iv[1] for iv in merged]

    count = 0

    # Check each house
    for hx, hy in houses:
        visited = False

        # Check if house is on any vertical segment
        if hx in vert_starts:
            starts = vert_starts[hx]
            # Find the interval with the largest start <= hy
            # bisect_right returns insertion point after all elements <= hy
            idx = bisect_right(starts, hy) - 1
            if idx >= 0:
                # Check if hy is within the interval's end
                if hy <= vert_ends[hx][idx]:
                    visited = True

        # If not visited vertically, check horizontal segments
        if not visited:
            if hy in horz_starts:
                starts = horz_starts[hy]
                # Find the interval with the largest start <= hx
                idx = bisect_right(starts, hx) - 1
                if idx >= 0:
                    # Check if hx is within the interval's end
                    if hx <= horz_ends[hy][idx]:
                        visited = True

        if visited:
            count += 1

    print(f"{curr_x} {curr_y} {count}")

if __name__ == '__main__':
    solve()
